# Wiki save script

Install: write the code below verbatim to `tools/save.py` in the kit folder and `chmod +x` it (wiki-kit-setup does this). Run `python3 tools/save.py --help` for modes. Modes: crm (person, company, fact, loop, set), family (record, fact), notes (item, append), articles (item, append); each also has `page` and `find`. Always `find` before creating. Exit codes: 0 ok, 2 duplicate (fine), 3 secret blocked, 4 lock busy (retry), 5 bad input or mode folder missing, 6 git error. Env: WIKI_TZ (date zone), WIKI_OWNER_NAMES (owner never gets a crm page), WIKI_LOCK_WAIT. Pass `--bot <name>` so commits show who saved.

````python
#!/usr/bin/env python3
"""The one save path for the wiki; every bot saves through it. Prints one JSON line. See README.md.

  crm person|company|fact|loop|set   family record|fact   articles item|append   notes item|append
  <mode> page --path P --file full.md (whole page)   find --url|--source-id|--title|--email|--phone|--whatsapp-id|--slack-id
A mode whose top folder is missing from the wiki is disabled. Run `save.py <mode> <action> -h` for flags.
Env: WIKI_TZ (dates, default UTC), WIKI_OWNER_NAMES (comma list; the owner never gets a crm page).
Exit: 0 ok, 2 duplicate/identity conflict, 3 secret (nothing written), 4 lock busy, 5 bad input, 6 git error.
"""
import argparse, datetime, email.utils, fcntl, json, os, re, shutil, subprocess, sys, tempfile, time, unicodedata
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
FAMILY_KINDS = ("documents", "finance-and-admin", "health", "household", "labs", "observations", "travel")
CRM_SECTIONS = ["Relationship summary", "Personal context", "Work context", "Preferences / style", "Open loops",
                "Recent interactions", "Key people", "Commercial terms", "Organization identity",
                "Sensitive / handle carefully", "Open loop status", "Resolution history"]
NOTE_CATEGORIES = ("media", "food", "shopping", "reference", "travel", "work", "personal", "tech", "home",
                   "health", "finance", "family", "events", "places")
CRM_SET_SCALAR = {"birthday", "relation", "company", "role", "linkedin", "status", "sensitivity", "last_interaction", "due"}
DATE_FIELDS = {"birthday": r"(\d{4}-)?\d{2}-\d{2}", "last_interaction": r"\d{4}-\d{2}-\d{2}", "due": r"\d{4}-\d{2}-\d{2}"}
CRM_SET_LIST = {"aliases", "emails", "phones", "whatsapp_ids", "slack_ids", "category_tags"}
SECRET_PATTERNS = [r"(?i)\b(password|passwd|pwd|contrase(n|ñ)a|clave|senha)\s*[:=]\s*\S{4,}",
                   r"(?i)\b(otp|2fa|verification|login|security|verificaci[oó]n) (code|c[oó]digo)\s*[:=]?\s*\d{4,8}\b",
                   r"gh[pousr]_[A-Za-z0-9]{30,}", r"sk-[A-Za-z0-9_-]{20,}", r"xox[abpr]-[A-Za-z0-9-]{10,}",
                   r"AKIA[0-9A-Z]{16}", r"-----BEGIN [A-Z ]*PRIVATE KEY-----",
                   r"(?i)\b(iban|account (number|no)\.?|routing number|n[uú]mero de cuenta)\W{0,5}[A-Z]{0,4}\d[\d -]{7,}"]
DOC_NUMBER = r"(?i)\b(passport|pasaporte|c[eé]dula|dni|ssn|license|licencia)\b\W{0,15}(n(o|umber|ro|úmero)?\.?\s*)?[A-Z]{0,3}[\d.\- ]{6,}"
OWNER = [n.strip().lower() for n in os.environ.get("WIKI_OWNER_NAMES", "").split(",") if n.strip()]

class Fail(Exception):
    def __init__(self, code, msg, extra=None): super().__init__(msg); self.code = code; self.extra = extra or {}

def today():
    try:
        from zoneinfo import ZoneInfo
        tz = ZoneInfo(os.environ.get("WIKI_TZ") or "UTC")
    except Exception: tz = datetime.timezone.utc
    return datetime.datetime.now(tz).date().isoformat()

def slugify(s, n=70):
    s = unicodedata.normalize("NFKD", str(s)).encode("ascii", "ignore").decode()
    return (re.sub(r"[^a-zA-Z0-9]+", "-", s).strip("-").lower()[:n].strip("-")) or "untitled"

def norm_text(s): return re.sub(r"\s+", " ", slugify(s, 100000).replace("-", " ")).strip()

def git(*args, check=True):
    r = subprocess.run(["git", "-C", str(ROOT), *args], capture_output=True, text=True)
    if check and r.returncode: raise Fail(6, f"git {' '.join(args)}: {r.stderr.strip()[:400]}")
    return r

def split_fm(text):
    import yaml
    if text.startswith("---\n"):
        end = text.find("\n---", 4)
        if end != -1:
            try: return (yaml.safe_load(text[4:end]) or {}), text[end + 4:].lstrip("\n")
            except Exception: return {}, text
    return {}, text

def join_fm(fm, body):
    import yaml
    return f"---\n{yaml.safe_dump(fm, allow_unicode=True, sort_keys=False, width=10_000).strip()}\n---\n\n{body.strip()}\n"

def as_list(v): return [] if v in (None, "") else (v if isinstance(v, list) else [v])
def clean(fm): return {k: v for k, v in fm.items() if v not in (None, [], "")}
def rel_of(p): return p.relative_to(ROOT).as_posix()
def load(p): return split_fm(p.read_text(encoding="utf-8", errors="replace"))
def is_owner(name): return bool(name) and any(re.search(rf"(?i)\b{re.escape(o)}\b", name) for o in OWNER)

def read_body(a, required=True):
    if not a.body_file:
        if required: raise Fail(5, "--body-file is required")
        return None
    body = (sys.stdin.read() if a.body_file == "-" else Path(a.body_file).read_text(encoding="utf-8")).strip()
    if body.startswith("---\n"): raise Fail(5, "body file must not contain frontmatter (use `page` for whole pages)")
    body = re.sub(r"^#\s+.*\n+", "", body)
    if not body: raise Fail(5, "empty body")
    return body

def check_rel(rel, domain):
    rel = rel.strip().lstrip("./").strip("/")
    if ".." in rel or not rel.endswith(".md") or rel.split("/")[0] != domain:
        raise Fail(5, f"path must be {domain}/.../*.md inside the wiki")
    return rel

def pages(domain, sub=None):
    base = ROOT / domain / (sub or "")
    for p in sorted(base.rglob("*.md")):
        if "/assets/" not in p.as_posix(): yield p

def fact_line(a, text=None):
    text = (text if text is not None else a.fact or "").strip()
    if not text: raise Fail(5, "--fact is required")
    if "\n" in text or len(text) > 700: raise Fail(5, "a fact is one line of at most 700 chars; paraphrase, never paste raw messages")
    if not a.source: raise Fail(5, "--source <id> is required (e.g. gmail:<thread>, slack:<channel>:<ts>, meeting:<id>)")
    ch = f" ({a.channel})" if getattr(a, "channel", None) else ""
    return f"- {a.date or today()}{ch}: {text} (Source: {a.source})"

def add_to_section(body, section, line, newest_first=False):
    if line.strip() in (l.strip() for l in body.split("\n")): return body, False
    lines = body.rstrip("\n").split("\n")
    idx = next((i for i, l in enumerate(lines) if re.match(rf"^##\s+{re.escape(section)}\s*$", l, re.I)), None)
    if idx is None: lines += ["", f"## {section}", line]
    elif newest_first:
        j = idx + 1
        while j < len(lines) and not lines[j].strip(): j += 1
        lines.insert(j, line)
    else:
        end = next((j for j in range(idx + 1, len(lines)) if re.match(r"^##\s", lines[j])), len(lines))
        while end > idx + 1 and not lines[end - 1].strip(): end -= 1
        lines.insert(end, line)
    return "\n".join(lines) + "\n", True

def supersede(body, needle, date):
    lines = body.split("\n")
    for i, l in enumerate(lines):
        if needle.lower() in l.lower() and l.lstrip().startswith("- ") and "(until " not in l:
            lines[i] = l.rstrip() + f" (until {date})"; return "\n".join(lines)
    raise Fail(5, f"--supersede text not found: {needle[:60]}")

def section_name(s, allowed):
    if not s: return None
    s2 = {"preferences": "Preferences / style", "sensitive": "Sensitive / handle carefully"}.get(s.lower(), s)
    for x in allowed:
        if x.lower() == s2.lower(): return x
    raise Fail(5, f"--section must be one of {allowed}")

def norm_url(u):
    u = re.sub(r"^https?://(www\.|mobile\.|m\.)?", "", u.strip())
    u = re.sub(r"[?&](s|t|utm_[a-z]+|ref|ref_src|usp|fbclid|igshid)=[^&#]*", "", u).rstrip("?&/")
    u = re.sub(r"^(twitter|x)\.com/(i/web|[^/]+)/status/", "x.com/status/", u.replace("twitter.com/", "x.com/"))
    return u.lower()


# ---------------------------------------------------------------- dedupe / identity
def find_by_keys(domain, url=None, source_id=None, title=None, body=None, sub=None):
    """Match order: source id > normalized URL > same body > title or alias slug."""
    if not (ROOT / domain).is_dir(): return []
    nu = norm_url(url) if url else None
    nb = norm_text(body)[:400] if body else None
    ts = slugify(title) if title else None
    hits = []
    for p in pages(domain, sub):
        fm, b = load(p)
        urls = [str(x) for k in ("url", "urls") for x in as_list(fm.get(k))]
        why = None
        if source_id and str(fm.get("source_id") or "") == source_id: why = "source_id"
        elif nu and any(norm_url(u) == nu for u in urls): why = "url"
        elif nb and len(nb) > 40 and nb in norm_text(b): why = "body"
        elif ts and (slugify(str(fm.get("title") or "")) == ts or ts in [slugify(x) for x in as_list(fm.get("aliases"))]): why = "title"
        if why: hits.append({"path": rel_of(p), "match": why, "title": fm.get("title")})
    order = {"source_id": 0, "url": 1, "body": 2, "title": 3}
    return sorted(hits, key=lambda h: order[h["match"]])

def norm_id(kind, v):
    v = str(v).strip()
    if kind == "emails": return v.lower()
    if kind in ("phones", "whatsapp_ids"):
        local = v.split("@")[0]
        return re.sub(r"\D", "", local) if re.fullmatch(r"\+?[\d\s().-]{7,}", local) else v.lower()
    return v.upper() if kind == "slack_ids" else v

ROLE_NAMES = re.compile(r"(?i)\b(no-?reply|do-?not-?reply|support|team|info|hello|notifications?|billing|admin|sales|newsletter|mailer|calendar|via)\b")

def parse_email(v):
    name, addr = email.utils.parseaddr(str(v).strip())
    addr = (addr or str(v)).strip().lower()
    name = re.sub(r"\s+", " ", name.strip().strip("'\"")).strip()
    if not name or "@" in name or not re.search(r"[^\W\d_]{2}", name) or ROLE_NAMES.search(name) \
       or name.lower() == addr.split("@")[0].lower(): name = None
    return name, addr

def hard_ids(a):
    e164 = lambda v: ("+" + re.sub(r"\D", "", v)) if re.fullmatch(r"\+?[\d\s().-]{7,}", v.strip()) else v
    out = {"emails": [parse_email(x)[1] for x in a.email or []], "phones": [e164(x) for x in a.phone or []],
           "whatsapp_ids": a.whatsapp_id or [], "slack_ids": a.slack_id or []}
    return {k: [str(x).strip() for x in v if str(x).strip()] for k, v in out.items() if v}

def identity_matches(ids):
    key = lambda k, v: ("phone" if k in ("phones", "whatsapp_ids") else k, norm_id(k, v))
    want = {key(k, v) for k, vs in ids.items() for v in vs}
    hits = []
    if not (ROOT / "crm").is_dir(): return hits
    for p in pages("crm"):
        fm, _ = load(p)
        common = want & {key(k, v) for k in ("emails", "phones", "whatsapp_ids", "slack_ids") for v in as_list(fm.get(k))}
        if common: hits.append({"path": rel_of(p), "match": "identity", "title": fm.get("title"), "on": sorted(v for _, v in common)})
    return hits

def resolve_target(a, domain):
    if getattr(a, "path", None): rel = check_rel(a.path, domain)
    elif getattr(a, "to", None):
        if "<" in a.to: a.to = parse_email(a.to)[1]
        k = "emails" if "@" in a.to and "." in a.to.split("@")[-1] and "whatsapp" not in a.to else ("slack_ids" if re.fullmatch(r"[UW][A-Z0-9]{6,}", a.to) else "phones")
        m = identity_matches({k: [a.to]})
        if len(m) != 1: raise Fail(2 if m else 5, f"--to matched {len(m)} pages", {"duplicates": m})
        rel = m[0]["path"]
    else: raise Fail(5, "--path or --to is required")
    if not (ROOT / rel).exists(): raise Fail(5, f"{rel} does not exist")
    return rel

# ---------------------------------------------------------------- CRM
def merge_ids(fm, ids, aliases):
    for k, vs in ids.items():
        cur = as_list(fm.get(k)); seen = {norm_id(k, x) for x in cur}
        for v in vs:
            if norm_id(k, v) not in seen: cur.append(v); seen.add(norm_id(k, v))
        fm[k] = cur
    new = [x for x in aliases or [] if x not in as_list(fm.get("aliases")) and x != fm.get("title")]
    if new: fm["aliases"] = as_list(fm.get("aliases")) + new

def crm_fact_into(a, fm, body):
    sec = section_name(a.section, CRM_SECTIONS) or ("Recent interactions" if a.channel else "Work context")
    d = a.date or today()
    if a.supersede: body = supersede(body, a.supersede, d)
    body, changed = add_to_section(body, sec, fact_line(a), newest_first=(sec == "Recent interactions"))
    if sec == "Recent interactions" and str(fm.get("last_interaction") or "") < d: fm["last_interaction"] = d
    return fm, body, changed or bool(a.supersede)

def meta(a, d): return {"created": d, "updated": d, "saved_by": a.bot, "source": f"save.py:{a.bot}:{d}"}

def promote(a, rel, fm, body, notes):
    """An unresolved contact matched on a hard id and the source names them: move it to crm/people."""
    slug = slugify(a.name); new = f"crm/people/{slug}.md"
    if (ROOT / new).exists() or find_by_keys("crm", title=a.name, sub="people"):
        notes.append(f"not promoted: {new} or a page titled {a.name!r} exists; review the pair"); return rel, body, []
    fm.update(id=f"person/{slug}", title=a.name, status="active"); merge_ids(fm, {}, [Path(rel).stem])
    body = re.sub(r"(?m)^# Person: .*$", f"# Person: {a.name}", body, count=1)
    return new, re.sub(r"(?m)^- Identity not proven yet;.*\n?", "", body), [(rel, None)]

def crm_person(a):
    ids = hard_ids(a)
    if not ids: raise Fail(5, "never create or merge from a name alone: pass --email/--phone/--whatsapp-id/--slack-id")
    a.name = a.name or next((n for n in (parse_email(v)[0] for v in a.email or []) if n and not is_owner(n)), None)
    if is_owner(a.name): raise Fail(5, "the wiki owner has no crm page")
    m = identity_matches(ids); d = a.date or today()
    if len(m) > 1: raise Fail(2, "identifiers match several CRM pages; do not merge, list for review", {"duplicates": m})
    if m:
        rel = m[0]["path"]; fm, body = load(ROOT / rel); notes, extra = [], []
        merge_ids(fm, ids, (a.alias or []) + ([a.name] if a.name and fm.get("status") != "unresolved" else []))
        for k in ("company", "role", "linkedin"):
            v = getattr(a, k)
            if v and not fm.get(k): fm[k] = v
            elif v and str(fm.get(k)) != v: notes.append(f"{k} differs ({fm.get(k)!r} on page); change it with `crm set`")
        if a.name and rel.startswith("crm/unresolved/"): rel, body, extra = promote(a, rel, fm, body, notes)
        if a.fact: fm, body, _ = crm_fact_into(a, fm, body)
        fm["updated"] = d
        return [(rel, join_fm(fm, body))] + extra, {"merged_into": rel, "notes": notes}, "person", rel
    if a.name:
        slug = slugify(a.name); rel = f"crm/people/{slug}.md"
        same = find_by_keys("crm", title=a.name, sub="people") + ([{"path": rel, "match": "slug"}] if (ROOT / rel).exists() else [])
        if same: raise Fail(2, "same name, different identifiers: no merge; add the id with `crm set` only on hard evidence", {"duplicates": same})
        fm = {"id": f"person/{slug}", "type": "person", "title": a.name, "aliases": a.alias or [], "domain": "crm", "status": "active",
              "sensitivity": a.sensitivity or "normal", **ids, "company": a.company, "role": a.role, "linkedin": a.linkedin, **meta(a, d)}
        body = f"# Person: {a.name}\n\n## At a glance\n- CRM type: person\n" + (f"- Company: [[crm/companies/{slugify(a.company)}|{a.company}]]\n" if a.company else "") + (f"- Role: {a.role}\n" if a.role else "")
    else:
        if not a.fact: raise Fail(5, "an unresolved contact is only saved together with a real --fact")
        first = next(v for vs in ids.values() for v in vs); slug = "unresolved-" + slugify(first); rel = f"crm/unresolved/{slug}.md"
        fm = {"id": f"person/{slug}", "type": "person", "title": f"Unresolved: {first}", "aliases": a.alias or [], "domain": "crm",
              "status": "unresolved", "sensitivity": a.sensitivity or "private", **ids, **meta(a, d)}
        body = "# Person: Unnamed contact\n\n## At a glance\n- Identity not proven yet; merge into crm/people only on hard evidence.\n"
    fm = clean(fm)
    if a.fact: fm, body, _ = crm_fact_into(a, fm, body)
    return [(rel, join_fm(fm, body))], {"created": rel}, "person", rel

def crm_company(a):
    if not a.name: raise Fail(5, "--name is required")
    d = a.date or today(); slug = slugify(a.name); site = norm_url(a.website).split("/")[0] if a.website else None
    hits = [h for t in [a.name] + (a.alias or []) for h in find_by_keys("crm", title=t, sub="companies")] + (find_by_keys("crm", url=site, sub="companies") if site else [])
    uniq = list({h["path"]: h for h in hits}.values())
    if len(uniq) > 1: raise Fail(2, "company matches several pages; pick one and use `crm fact --path`", {"duplicates": uniq})
    if uniq:
        rel = uniq[0]["path"]; fm, body = load(ROOT / rel); merge_ids(fm, {}, a.alias)
        if a.fact: fm, body, _ = crm_fact_into(a, fm, body)
        fm["updated"] = d
        return [(rel, join_fm(fm, body))], {"merged_into": rel}, "company", rel
    rel = f"crm/companies/{slug}.md"
    fm = clean({"id": f"company/{slug}", "type": "company", "title": a.name, "aliases": a.alias or [], "domain": "crm", "status": "active",
                "sensitivity": a.sensitivity or "normal", "url": site, **meta(a, d)})
    body = f"# Company: {a.name}\n\n## At a glance\n- CRM type: company\n" + (f"- Domain: {site}\n" if site else "")
    if a.fact: fm, body, _ = crm_fact_into(a, fm, body)
    return [(rel, join_fm(fm, body))], {"created": rel}, "company", rel

def crm_fact(a):
    rel = resolve_target(a, "crm"); fm, body = load(ROOT / rel)
    fm, body, changed = crm_fact_into(a, fm, body)
    if not changed: return [], {"changed": False, "note": "already present"}, "fact", rel
    fm["updated"] = a.date or today()
    return [(rel, join_fm(fm, body))], {}, "fact", rel

def crm_loop(a):
    if not (a.title and a.owner and a.direction and a.source): raise Fail(5, "--title, --owner, --direction and --source are required")
    d = a.date or today(); slug = slugify(a.title); rel = f"crm/open-loops/{slug}.md"
    dupes = [h for h in find_by_keys("crm", title=a.title, sub="open-loops") if load(ROOT / h["path"])[0].get("status") == "open"]
    if dupes and not a.update: raise Fail(2, "an open loop with this title exists; add to it with `crm fact`", {"duplicates": dupes})
    if (ROOT / rel).exists(): rel = f"crm/open-loops/{slug}-{d}.md"; slug = Path(rel).stem
    fm = clean({"id": f"open-loop/{slug}", "type": "open_loop", "title": a.title, "domain": "crm", "status": "open", "owner": a.owner,
                "direction": a.direction, "due": a.due, "people": a.person or [], "company": a.company, **meta(a, d)})
    people = ", ".join(f"[[crm/people/{slugify(p)}|{p}]]" for p in a.person or []) or "Unknown"
    body = (f"# Open loop: {a.title}\n\n## Relationship summary\n{a.context or a.title}\n\n## Open loop status\n- Owner: {a.owner}\n"
            f"- Direction: {a.direction}\n- Due: {a.due or 'none'}\n- People: {people}\n\n## Resolution history\n- {d}: opened. (Source: {a.source})\n")
    return [(rel, join_fm(fm, body))], {"created": rel}, "loop", rel

def crm_set(a):
    rel = resolve_target(a, "crm"); fm, body = load(ROOT / rel)
    if not a.field: raise Fail(5, "--field key=value is required")
    for kv in a.field:
        k, _, v = (x.strip() for x in kv.partition("="))
        if not v: raise Fail(5, f"bad --field {kv}")
        if k == "aliases": merge_ids(fm, {}, [v])
        elif k in CRM_SET_LIST: merge_ids(fm, {k: [v]}, [])
        elif k in CRM_SET_SCALAR:
            if k in DATE_FIELDS and not re.fullmatch(DATE_FIELDS[k], v): raise Fail(5, f"{k} must match {DATE_FIELDS[k]}")
            if k == "sensitivity" and v not in ("normal", "sensitive", "private"): raise Fail(5, "sensitivity must be normal|sensitive|private")
            fm[k] = v
        else: raise Fail(5, f"field {k} not settable; allowed: {sorted(CRM_SET_SCALAR | CRM_SET_LIST)}")
    fm["updated"] = a.date or today()
    return [(rel, join_fm(fm, body))], {}, "set", rel

# ---------------------------------------------------------------- FAMILY
def merge_old(rel, fm):
    old, _ = load(ROOT / rel); return {**old, **{k: v for k, v in fm.items() if k not in ("id", "created")}}

def family_record(a):
    if a.kind not in FAMILY_KINDS: raise Fail(5, f"--kind must be one of {FAMILY_KINDS}")
    if not a.title: raise Fail(5, "--title is required")
    d = a.date or today(); slug = slugify(a.title)
    body = read_body(a, required=False) or f"## Facts\n{fact_line(a)}"
    dupes = find_by_keys("family", source_id=a.source_id, title=a.title, sub=f"records/{a.kind}")
    if dupes and not a.update: raise Fail(2, "record exists; add to it with `family fact --path`", {"duplicates": dupes})
    rel = dupes[0]["path"] if dupes else f"family/records/{a.kind}/{d}-{slug}.md"
    fm = clean({"id": f"family/record.{slug}-{d}", "type": "record", "kind": a.kind, "title": a.title, "domain": "family", "tags": a.tag or [],
                "sensitivity": a.sensitivity or ("sensitive" if a.kind in ("health", "labs", "documents", "finance-and-admin") else "private"),
                "people": a.people or [], "source_id": a.source_id, **meta(a, d)})
    if dupes: fm = merge_old(rel, fm)
    return [(rel, join_fm(fm, f"# {a.title}\n\n{body}"))], {}, "record", rel

def family_fact(a):
    if a.person and not a.path:
        rel = f"family/entities/people/{slugify(a.person)}.md"
        if not (ROOT / rel).exists(): raise Fail(5, f"no {rel}; family pages: {[p.stem for p in pages('family', 'entities/people')]}. Others are CRM contacts")
    else: rel = resolve_target(a, "family")
    fm, body = load(ROOT / rel)
    body, changed = add_to_section(body, a.section or "Facts", fact_line(a))
    if not changed: return [], {"changed": False, "note": "already present"}, "fact", rel
    fm["updated"] = a.date or today()
    return [(rel, join_fm(fm, body))], {}, "fact", rel

# ---------------------------------------------------------------- ARTICLES / NOTES
def articles_item(a):
    if not (a.title and a.url): raise Fail(5, "--title and --url are required")
    body = read_body(a); url = a.url[0]; d = a.date or today()
    heads = {h.strip().lower() for h in re.findall(r"^##\s+(.+)$", body, re.M)}
    missing = [n for n, o in (("TL;DR", {"tl;dr", "core idea"}), ("Key learnings", {"key bullets", "key learnings"}), ("Why this matters", {"why this matters"})) if not heads & o]
    if missing: raise Fail(5, f"article body needs ## sections: {missing}")
    if len(body) > 60000: raise Fail(5, "body over 60k chars; keep a summary and the link, not the full text")
    dupes = find_by_keys("articles", url=url, title=a.title, sub="items")
    if dupes and not a.update: raise Fail(2, "article already saved; pass --update to refresh it", {"duplicates": dupes})
    slug = f"{d}-{slugify(a.title, 60)}"
    rel = dupes[0]["path"] if dupes else f"articles/items/{d[:4]}/{d[5:7]}/{slug}.md"
    fm = clean({"id": f"article/{slug}", "type": "article", "title": a.title, "domain": "articles", "url": url, "author": a.author,
                "source_type": a.source_type or "article", "tags": a.tag or [], **meta(a, d)})
    if dupes: fm = merge_old(rel, fm)
    return [(rel, join_fm(fm, f"# {a.title}\n\n{body}"))], {}, "item", rel

def generic_append(a, domain, default_section):
    rel = check_rel(a.path or "", domain)
    if not (ROOT / rel).exists(): raise Fail(5, f"{rel} does not exist")
    text = (a.line or "").strip()
    if not text or "\n" in text: raise Fail(5, "--line must be one line")
    line = text if text.startswith("- ") else (fact_line(a, text) if a.source else f"- {a.date or today()}: {text}")
    fm, body = load(ROOT / rel)
    body, changed = add_to_section(body, a.section or default_section, line)
    if not changed: return [], {"changed": False, "note": "already present"}, "append", rel
    if fm: fm["updated"] = a.date or today()
    return [(rel, join_fm(fm, body) if fm else body)], {}, "append", rel

def notes_item(a):
    if not a.title: raise Fail(5, "--title is required")
    cat = (a.category or "").lower()
    if cat not in NOTE_CATEGORIES and not (cat and a.new_category): raise Fail(5, f"--category must be one of {NOTE_CATEGORIES} (or --new-category)")
    d = a.date or today(); body = read_body(a, required=False)
    if body is None:
        if not a.summary: raise Fail(5, "--summary (or --body-file with ## Summary) is required")
        det = ([f"- Why saved: {a.why}"] if a.why else []) + [f"- {x}" for x in a.details or []]
        body = (f"## Summary\n{a.summary.strip()}\n\n## Details\n" + ("\n".join(det) or "- (none yet)") + "\n\n## Links\n" +
                ("\n".join(f"- {u}" for u in a.url or []) or "- (none)") + f"\n\n## Status\nSaved {d} by {a.bot}\n")
    elif "## summary" not in body.lower(): raise Fail(5, "note body needs ## Summary, ## Details, ## Links, ## Status")
    if len(body) > 20000: raise Fail(5, "note over 20k chars; never store raw chat exports")
    dupes = find_by_keys("notes", url=(a.url or [None])[0], source_id=a.source_id, title=a.title, body=a.summary)
    if dupes and not a.update: raise Fail(2, "already saved; use `notes append --path` or --update", {"duplicates": dupes})
    rel = dupes[0]["path"] if dupes else f"notes/{d[:4]}/{d}-{slugify(a.title)}.md"
    if not dupes and (ROOT / rel).exists(): rel = rel[:-3] + "-2.md"
    fm = clean({"id": f"note/{Path(rel).stem}", "type": "note", "title": a.title, "aliases": a.alias or [], "domain": "notes", "status": "active",
                "tags": a.tag or [], "sensitivity": a.sensitivity or "normal", "category": cat, "item_type": a.item_type, "urls": a.url or [],
                "source_id": a.source_id, **meta(a, d)})
    if dupes: fm = merge_old(rel, fm)
    return [(rel, join_fm(fm, f"# {a.title}\n\n{body}"))], {}, "item", rel

def mode_page(a, domain):
    rel = check_rel(a.path or "", domain)
    if not a.file: raise Fail(5, "--file is required")
    text = sys.stdin.read() if a.file == "-" else Path(a.file).read_text(encoding="utf-8")
    fm, _ = split_fm(text)
    if any(not fm.get(k) for k in ("id", "type", "title")) or fm.get("domain") != domain: raise Fail(5, f"frontmatter needs id, type, title and domain: {domain}")
    return [(rel, text)], {}, "page", rel

# mode: (actions, string flags, list flags, bool flags)
MODES = {
    "crm": ({"person": crm_person, "company": crm_company, "fact": crm_fact, "loop": crm_loop, "set": crm_set},
            ("--name", "--company", "--role", "--linkedin", "--website", "--to", "--supersede", "--owner", "--direction", "--due", "--context"),
            ("--email", "--phone", "--whatsapp-id", "--slack-id", "--person", "--field"), ()),
    "family": ({"record": family_record, "fact": family_fact}, ("--kind", "--person"), ("--people",), ()),
    "articles": ({"item": articles_item, "append": lambda a: generic_append(a, "articles", "Updates")}, ("--author", "--source-type"), (), ()),
    "notes": ({"item": notes_item, "append": lambda a: generic_append(a, "notes", "Details")},
              ("--category", "--item-type", "--summary", "--why"), ("--details",), ("--new-category",)),
}
for _n, _m in MODES.items(): _m[0]["page"] = (lambda d: lambda a: mode_page(a, d))(_n)
NO_DOC_NUMBERS = ("crm", "family")

# ---------------------------------------------------------------- plumbing
def luhn(d): return sum(x if i % 2 == 0 else (x * 2 - 9 if x > 4 else x * 2) for i, x in enumerate(reversed(d))) % 10 == 0

def secret_check(rel, text):
    for pat in SECRET_PATTERNS:
        if re.search(pat, text): return "credential-like text"
    for m in re.finditer(r"\b(?:\d[ -]?){12,18}\d\b", text):
        if text[m.end():m.end() + 1] in ("@", "-") or text[max(0, m.start() - 1):m.start()] in (":", "-", "/"): continue
        d = [int(c) for c in re.sub(r"\D", "", m.group())]
        if 13 <= len(d) <= 19 and luhn(d) and re.search(r"(?i)\b(card|tarjeta|visa|master(card)?|amex|cc)\b", text[max(0, m.start() - 60):m.start()]):
            return "card number"
    if rel.split("/")[0] in NO_DOC_NUMBERS:
        m = re.search(DOC_NUMBER, text)
        if m and sum(c.isdigit() for c in m.group()) >= 6: return "full document number (store that it exists, its expiry and where the file lives)"
    gl = shutil.which("gitleaks") or os.path.expanduser("~/.local/bin/gitleaks")
    if os.path.exists(gl):
        with tempfile.TemporaryDirectory() as td:
            Path(td, Path(rel).name).write_text(text, encoding="utf-8")
            if subprocess.run([gl, "dir", td, "--redact", "--no-banner", "--exit-code", "1"], capture_output=True).returncode == 1: return "gitleaks finding"
    return None

def atomic_write(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp = tempfile.mkstemp(dir=path.parent, prefix=".save-", suffix=".tmp")
    with os.fdopen(fd, "w", encoding="utf-8") as f: f.write(text if text.endswith("\n") else text + "\n")
    os.replace(tmp, path)

def locked(timeout=float(os.environ.get("WIKI_LOCK_WAIT", 180))):
    f = open(ROOT / ".git" / "save.lock", "w"); t0 = time.time()
    while True:
        try: fcntl.flock(f, fcntl.LOCK_EX | fcntl.LOCK_NB); return f
        except BlockingIOError:
            if time.time() - t0 > timeout: raise Fail(4, f"save.lock busy for {timeout}s; retry later")
            time.sleep(0.5)

def sync(has_remote):
    if not has_remote: return True
    r = git("pull", "--rebase", "--autostash", "--quiet", check=False)
    if r.returncode: git("rebase", "--abort", check=False); return False
    return True

def push(has_remote, tries=5):
    if not has_remote: return {"pushed": False, "push_note": "no remote"}
    for i in range(tries):
        if not git("push", "--quiet", check=False).returncode: return {"pushed": True}
        time.sleep(0.5 * (i + 1))
        if not sync(True): return {"pushed": False, "push_note": "rebase conflict; commit kept locally, resolve by hand"}
    return {"pushed": False, "push_note": f"push failed {tries} times; commit kept locally, the next save pushes it"}

def reindex(rel):
    try:
        sys.path.insert(0, str(ROOT / "tools"))
        import contextlib, io, search
        with contextlib.redirect_stdout(io.StringIO()): search.build(False, vacuum=False)
        title = (load(ROOT / rel)[0].get("title") if (ROOT / rel).exists() else None) or Path(rel).stem.replace("-", " ")
        hits = [r["path"] for r in search.search(str(title), k=5, domain=rel.split("/")[0])]
        return {"indexed": True, "rank_for_title": hits.index(rel) + 1 if rel in hits else None}
    except Exception as e: return {"indexed": False, "index_error": str(e)[:200]}

def run(a):
    if a.mode == "find":
        ids = hard_ids(a); out = identity_matches(ids) if ids else []
        for dom in [a.find_mode] if a.find_mode else MODES:
            if a.url or a.source_id or a.title: out += find_by_keys(dom, url=(a.url or [None])[0], source_id=a.source_id, title=a.title)
        print(json.dumps({"ok": True, "duplicates": out}, ensure_ascii=False)); return
    if not a.bot or not a.bot.strip() or len(a.bot) > 40 or "\n" in a.bot: raise Fail(5, "--bot <name> is required (max 40 chars)")
    if not (ROOT / a.mode).is_dir(): raise Fail(5, f"mode {a.mode} is not enabled in this wiki (no {a.mode}/ folder)")
    if not (ROOT / ".git").exists(): raise Fail(6, f"{ROOT} is not a git repository")
    has_remote = bool(git("remote").stdout.strip())
    ident = ("-c", f"user.name={a.bot}", "-c", f"user.email={git('config', 'user.email', check=False).stdout.strip() or 'bots@wiki.local'}")
    lockf = locked()
    try:
        synced = a.dry_run or sync(has_remote)
        writes, extra, kind, main_rel = MODES[a.mode][0][a.action](a)
        for rel, text in writes:   # scan only the lines this save adds
            if text is None: continue
            old = set((ROOT / rel).read_text(encoding="utf-8").split("\n")) if (ROOT / rel).exists() else set()
            leak = secret_check(rel, "\n".join(l for l in text.split("\n") if l not in old))
            if leak: raise Fail(3, f"{leak} in {rel}; nothing saved. Remove it and retry")
        res = {"ok": True, "path": main_rel, **extra}
        if not synced: res["sync_note"] = "pull --rebase failed; saved on the local checkout"
        if a.dry_run:
            print(writes[0][1][:2000] if writes and writes[0][1] else "", file=sys.stderr)
            res.update(dry_run=True, paths=[r for r, _ in writes]); print(json.dumps(res, ensure_ascii=False)); return
        rels = [r for r, _ in writes]
        for rel, text in writes:
            if text is None: (ROOT / rel).unlink(missing_ok=True)
            else: atomic_write(ROOT / rel, text)
        if rels:
            git("add", "-A", "--", *rels)
            if git("diff", "--cached", "--quiet", "--", *rels, check=False).returncode:
                git(*ident, "commit", "--quiet", "-m", f"{a.bot} save {a.mode}/{kind} {Path(main_rel).stem[:60]}", "--", *rels)
                res.update(files=rels, changed=True, commit=git("rev-parse", "--short", "HEAD").stdout.strip(), **push(has_remote))
            else: res["changed"] = False
        else: res.setdefault("changed", False)
        if not a.no_index and res.get("files"): res.update(reindex(main_rel))
    finally: lockf.close()
    print(json.dumps(res, ensure_ascii=False))

def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="mode", required=True)
    for name, (actions, flags, lflags, bflags) in MODES.items():
        asub = sub.add_parser(name).add_subparsers(dest="action", required=True)
        for act in actions:
            p = asub.add_parser(act)
            for f in ("--bot", "--date", "--title", "--body-file", "--file", "--path", "--line", "--section", "--source", "--source-id", "--fact", "--channel", *flags): p.add_argument(f)
            for f in ("--url", "--tag", "--alias", *lflags): p.add_argument(f, action="append")
            for f in ("--update", "--dry-run", "--no-index", *bflags): p.add_argument(f, action="store_true")
            p.add_argument("--sensitivity", choices=["normal", "sensitive", "private"])
    fp = sub.add_parser("find")
    fp.add_argument("--mode", dest="find_mode", choices=list(MODES)); fp.add_argument("--source-id"); fp.add_argument("--title")
    for f in ("--url", "--email", "--phone", "--whatsapp-id", "--slack-id"): fp.add_argument(f, action="append")
    a = ap.parse_args()
    try:
        if a.mode != "find" and a.date and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", a.date): raise Fail(5, "--date must be YYYY-MM-DD")
        run(a)
    except Fail as e:
        print(json.dumps({"ok": False, "code": e.code, "error": str(e), **e.extra}, ensure_ascii=False)); sys.exit(e.code)

if __name__ == "__main__":
    main()
