# Wiki search script

Install: write the code below verbatim to `tools/search.py` in the kit folder and `chmod +x` it (wiki-kit-setup does this). Commands: `build` (incremental; `--full` to rebuild), `query "text" [-k 10] [--domain crm|family|notes|articles] [--json] [--explain]`, `stats`. Hybrid keyword + typo-tolerant + optional semantic search (multilingual-e5-small, WIKI_MODEL dir; WIKI_EMBED=0 turns it off). Index lives in `.index/` (gitignored). Any bot that should use the wiki runs `query` and reads the top pages before answering.

````python
#!/usr/bin/env python3
"""Local hybrid search for the wiki: SQLite FTS5 keywords + rapidfuzz typo tolerance + optional
multilingual-e5-small (ONNX) embeddings, fused with Reciprocal Rank Fusion. Emails, URLs and long
numeric ids in the query jump straight to the pages that carry them.

  search.py build [--full]      incremental (or from-scratch) index into .index/wiki.sqlite
  search.py query "text" [-k 10] [--domain D] [--json] [--explain]
  search.py stats
Env: WIKI_MODEL (model dir, default ~/models/multilingual-e5-small), WIKI_EMBED=0 (keyword+fuzzy only),
     WIKI_DOMAINS (extra top-level folders to index, comma list). Synonyms: tools/synonyms.txt, one
     comma-separated group per line. Without onnxruntime/model the search falls back to keyword+fuzzy.
"""
import argparse, hashlib, json, os, re, sqlite3, sys, time, unicodedata
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
DB = ROOT / ".index" / "wiki.sqlite"
MODEL_DIR = Path(os.environ.get("WIKI_MODEL") or Path.home() / "models" / "multilingual-e5-small")
DOMAINS = tuple(dict.fromkeys(["crm", "family", "notes", "articles"] + [d.strip() for d in os.environ.get("WIKI_DOMAINS", "").split(",") if d.strip()]))
CHUNK_CHARS, MAX_CHUNKS, MAX_LEN, RRF_K = 900, 40, 256, 60
W_KEYWORD, W_SEMANTIC, W_TITLE_FULL, W_TITLE_PARTIAL, W_TITLE_SHORT = 1.0, 1.0, 1.5, 0.9, 0.5
SHORT_NAME, EXACT_BONUS, W_EXACT_MIXED, SIZE_DAMP = 5, (10.0, 5.0), 3.0, 0.04
STOP = {"de", "la", "el", "los", "las", "que", "en", "y", "a", "con", "por", "para", "del", "un", "una", "the", "of", "and", "to",
        "in", "for", "on", "with", "is", "what", "who", "did", "about", "me", "my"}

def _syn():
    f = Path(__file__).with_name("synonyms.txt"); out = {}
    for line in (f.read_text(encoding="utf-8").splitlines() if f.exists() else []):
        g = {w.strip().lower() for w in line.split(",") if w.strip() and not line.startswith("#")}
        for w in g: out[w] = sorted(g - {w})
    return out
SYN = _syn()

def strip_accents(s): return "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c))
def as_list(v): return [] if v is None else (v if isinstance(v, list) else [v])

def fix(s):
    try: return str(s).encode("utf-16", "surrogatepass").decode("utf-16")
    except UnicodeError: return str(s).encode("utf-8", "replace").decode("utf-8")

def split_fm(text):
    if text.startswith("---\n"):
        end = text.find("\n---", 4)
        if end != -1:
            import yaml
            try: fm = yaml.safe_load(text[4:end]) or {}
            except Exception: fm = {}
            return (fm if isinstance(fm, dict) else {}), text[end + 4:].lstrip("\n")
    return {}, text

def chunk_body(title, body):
    chunks, heading, buf = [], "", []
    def flush():
        txt = "\n".join(buf).strip()
        while len(txt) > CHUNK_CHARS * 1.5:
            cut = txt.rfind("\n", 0, CHUNK_CHARS); cut = cut if cut > CHUNK_CHARS // 3 else CHUNK_CHARS
            chunks.append((heading, txt[:cut].strip())); txt = txt[cut:].strip()
        if txt: chunks.append((heading, txt))
        buf.clear()
    for line in body.split("\n"):
        m = re.match(r"^#{1,6}\s+(.*)", line)
        if m: flush(); heading = m.group(1).strip(); continue
        buf.append(line)
        if sum(len(x) + 1 for x in buf) >= CHUNK_CHARS: flush()
    flush()
    return chunks or [("", title)]

# ---------------------------------------------------------------- exact keys
LONGID_RE = re.compile(r"(?<!\d)\d{15,20}(?!\d)")
EMAIL_RE = re.compile(r"[\w.+-]+@[\w-]+(?:\.[\w-]+)+")
URL_RE = re.compile(r"(?:https?://|www\.)[^\s<>\"'`\])|]+", re.I)
BARE_URL_RE = re.compile(r"(?<![@\w.])(?:[a-z0-9-]+\.)+[a-z]{2,}/[^\s<>\"'`]*", re.I)
DROP_PARAMS = re.compile(r"^(utm_\w+|s|t|si|ref|ref_src|fbclid|gclid|usp|igsh|mc_\w+)$", re.I)

def norm_url(u):
    u = re.sub(r"^https?://", "", u.strip().rstrip(".,;:!?*_~"), flags=re.I).split("#", 1)[0]
    host, _, rest = u.partition("/"); host = re.sub(r"^(www|mobile|m)\.", "", host.lower())
    host = {"twitter.com": "x.com"}.get(host, host)
    path, _, qs = rest.partition("?")
    keep = [kv for kv in qs.split("&") if kv and not DROP_PARAMS.match(kv.split("=", 1)[0])]
    path = path.rstrip("/")
    return host + ("/" + path if path else "") + ("?" + "&".join(keep) if keep else "")

def keys_in(text, query=False):
    out = set(LONGID_RE.findall(text)) | {m.group(0).lower().rstrip(".") for m in EMAIL_RE.finditer(text)}
    urls = URL_RE.findall(text) + (BARE_URL_RE.findall(text) if query else [])
    for u in urls:
        n = norm_url(u)
        if "." in n.split("/", 1)[0]: out.add("url:" + n)
    return out

def exact_keys(rel, text):
    fm_text, body = "", text
    if text.startswith("---\n") and (end := text.find("\n---", 4)) != -1: fm_text, body = text[4:end], text[end + 4:]
    keys = {k: 1 for k in keys_in(body)}
    keys.update({k: 0 for k in keys_in(rel + "\n" + fm_text)})
    return keys

# ---------------------------------------------------------------- embeddings (optional)
class Encoder:
    def __init__(self):
        import onnxruntime as ort
        from tokenizers import Tokenizer
        so = ort.SessionOptions(); so.intra_op_num_threads = min(4, os.cpu_count() or 1); so.enable_cpu_mem_arena = False
        self.sess = ort.InferenceSession(str(MODEL_DIR / "onnx" / "model_quantized.onnx"), so, providers=["CPUExecutionProvider"])
        self.inputs = {i.name for i in self.sess.get_inputs()}
        self.tok = Tokenizer.from_file(str(MODEL_DIR / "tokenizer.json"))
        self.tok.enable_truncation(MAX_LEN); self.tok.enable_padding(pad_id=1, pad_token="<pad>")

    def encode(self, texts, batch=16):
        import numpy as np
        out = []
        for i in range(0, len(texts), batch):
            enc = self.tok.encode_batch(texts[i:i + batch])
            ids = np.array([e.ids for e in enc], dtype=np.int64); mask = np.array([e.attention_mask for e in enc], dtype=np.int64)
            feed = {"input_ids": ids, "attention_mask": mask}
            if "token_type_ids" in self.inputs: feed["token_type_ids"] = np.zeros_like(ids)
            h = self.sess.run(None, feed)[0]; m = mask[..., None].astype(np.float32)
            v = (h * m).sum(1) / np.clip(m.sum(1), 1e-9, None)
            out.append((v / (np.linalg.norm(v, axis=1, keepdims=True) + 1e-12)).astype(np.float16))
        return np.vstack(out) if out else np.zeros((0, 384), dtype=np.float16)

def get_encoder():
    """The encoder, or None when embeddings are off or unavailable (keyword + fuzzy still work)."""
    if not hasattr(get_encoder, "enc"):
        get_encoder.enc = None
        if os.environ.get("WIKI_EMBED", "1") != "0" and (MODEL_DIR / "onnx" / "model_quantized.onnx").exists():
            try: get_encoder.enc = Encoder()
            except Exception as e: print(f"embeddings off: {e}", file=sys.stderr)
    return get_encoder.enc

# ---------------------------------------------------------------- index
SCHEMA = """
CREATE TABLE IF NOT EXISTS docs(path TEXT PRIMARY KEY, sha TEXT, domain TEXT, type TEXT, title TEXT, aliases TEXT, idents TEXT, status TEXT, updated TEXT);
CREATE TABLE IF NOT EXISTS chunks(id INTEGER PRIMARY KEY, path TEXT, heading TEXT, text TEXT, emb BLOB);
CREATE INDEX IF NOT EXISTS chunks_path ON chunks(path);
CREATE VIRTUAL TABLE IF NOT EXISTS fts USING fts5(title, aliases, heading, text, content='', contentless_delete=1, tokenize="unicode61 remove_diacritics 2");
CREATE VIRTUAL TABLE IF NOT EXISTS vocab USING fts5vocab(fts, row);
CREATE TABLE IF NOT EXISTS meta(k TEXT PRIMARY KEY, v TEXT);
CREATE TABLE IF NOT EXISTS keys(key TEXT, path TEXT, tier INTEGER, PRIMARY KEY(key, path)) WITHOUT ROWID;
"""

def connect():
    DB.parent.mkdir(exist_ok=True); con = sqlite3.connect(DB, timeout=60); con.executescript(SCHEMA); return con

def iter_files():
    for d in DOMAINS:
        for p in sorted((ROOT / d).rglob("*.md")):
            if "/assets/" not in p.as_posix(): yield p

def build(full=False, vacuum=True):
    t0 = time.time()
    if full and DB.exists(): DB.unlink()
    con = connect(); known = dict(con.execute("SELECT path, sha FROM docs")); seen, todo = set(), []
    for p in iter_files():
        text = p.read_text(encoding="utf-8", errors="replace"); rel = p.relative_to(ROOT).as_posix(); seen.add(rel)
        sha = hashlib.sha1(text.encode()).hexdigest()
        if known.get(rel) != sha: todo.append((p, rel, sha, text))
    def remove(rel):
        for (cid,) in con.execute("SELECT id FROM chunks WHERE path=?", (rel,)).fetchall(): con.execute("DELETE FROM fts WHERE rowid=?", (cid,))
        for t in ("chunks", "docs", "keys"): con.execute(f"DELETE FROM {t} WHERE path=?", (rel,))
    gone = [r for r in known if r not in seen]
    for rel in gone: remove(rel)
    enc = get_encoder() if todo else None
    print(f"files: {len(seen)}  changed/new: {len(todo)}  removed: {len(gone)}  embeddings: {'on' if enc else 'off'}", flush=True)
    for n, (p, rel, sha, text) in enumerate(todo, 1):
        remove(rel)
        con.executemany("INSERT OR REPLACE INTO keys VALUES(?,?,?)", [(k, rel, t) for k, t in exact_keys(rel, text).items()])
        fm, body = split_fm(text)
        title = fix(fm.get("title") or p.stem); aliases = [fix(a) for a in as_list(fm.get("aliases"))]
        idents = [fix(x) for k in ("emails", "phones", "whatsapp_ids", "slack_ids", "url", "website", "linkedin") for x in as_list(fm.get(k))]
        con.execute("INSERT INTO docs VALUES(?,?,?,?,?,?,?,?,?)", (rel, sha, rel.split("/")[0], str(fm.get("type") or ""), title,
                    json.dumps(aliases, ensure_ascii=False), json.dumps(idents, ensure_ascii=False), str(fm.get("status") or ""),
                    str(fm.get("updated") or fm.get("created") or "")))
        chunks = chunk_body(title, body); ctx = " ".join([title] + aliases)
        embs = enc.encode([f"passage: {ctx} | {h} | {t}" for h, t in chunks[:MAX_CHUNKS]]) if enc else []
        for i, (h, t) in enumerate(chunks):
            cur = con.execute("INSERT INTO chunks(path, heading, text, emb) VALUES(?,?,?,?)", (rel, h, t, embs[i].tobytes() if i < len(embs) else None))
            con.execute("INSERT INTO fts(rowid, title, aliases, heading, text) VALUES(?,?,?,?,?)",   # title/aliases on chunk 0 only
                        (cur.lastrowid, title if i == 0 else "", " ".join(aliases + idents) if i == 0 else "", h, t))
        if n % 100 == 0: con.commit(); print(f"  indexed {n}/{len(todo)}  {time.time() - t0:.0f}s", flush=True)
    con.execute("INSERT OR REPLACE INTO meta VALUES('built_at', ?)", (time.strftime("%Y-%m-%dT%H:%M:%S%z"),)); con.commit()
    if todo or gone: con.execute("INSERT INTO fts(fts) VALUES('optimize')"); con.commit()
    if vacuum: con.execute("VACUUM")
    print(f"done in {time.time() - t0:.0f}s -> {DB.relative_to(ROOT)}")

# ---------------------------------------------------------------- query
WORD = re.compile(r"[\w@.+-]+")

def load_vocab(con):
    if not hasattr(load_vocab, "v"):
        load_vocab.v = dict(con.execute("SELECT term, doc FROM vocab WHERE length(term) BETWEEN 2 AND 40"))
        load_vocab.keys = [k for k in load_vocab.v if 3 <= len(k) <= 30]
    return load_vocab.v

def fuzz():
    try: from rapidfuzz import fuzz as f, process as p; return f, p
    except ImportError: return None, None

def correct_terms(con, terms):
    f, proc = fuzz(); vocab = load_vocab(con); out = []
    for t in terms:
        alts = [t]
        if f and len(t) >= 4 and vocab.get(t, 0) < 2:
            cand = [k for k in load_vocab.keys if k[0] == t[0] and abs(len(k) - len(t)) <= 2] or load_vocab.keys
            alts += [k for k, s, _ in proc.extract(t, cand, scorer=f.ratio, limit=3) if s >= 80 and k != t]
        out.append(alts)
    return out

def split_word(vocab, t):
    """'glaresquare' -> 'glare square' when the word is rare and both halves are common."""
    if len(t) < 7 or vocab.get(t, 0) >= 2 or not t.isalpha(): return None
    best = max(((min(vocab.get(t[:i], 0), vocab.get(t[i:], 0)), f"{t[:i]} {t[i:]}") for i in range(3, len(t) - 2)), default=(0, None))
    return best[1] if best[0] >= 2 else None

def q_term(a): return '"' + a.replace('"', '') + '"' + ("*" if len(a) >= 4 and " " not in a else "")

def fts_groups(con, terms, fuzzy):
    vocab = load_vocab(con); alts = correct_terms(con, terms) if fuzzy else [[t] for t in terms]
    def one(i):
        xs = [q_term(a) for a in alts[i] + SYN.get(terms[i], [])]
        if (sp := split_word(vocab, terms[i])): xs.append(q_term(sp))
        return "(" + " OR ".join(xs) + ")"
    groups, i = [], 0
    while i < len(terms):
        j = terms[i] + terms[i + 1] if i + 1 < len(terms) else ""
        if len(j) >= 6 and j.isalnum() and vocab.get(j, 0) >= 1: groups.append(f"(({one(i)} AND {one(i + 1)}) OR {q_term(j)})"); i += 2
        else: groups.append(one(i)); i += 1
    return groups

def norm_name(s): return re.sub(r"\s+", " ", re.sub(r"[^\w@.+-]+", " ", strip_accents(str(s).lower()))).strip()

def title_match(qn, qtoks, qjoin, name):
    f, _ = fuzz(); n = norm_name(name)
    if not n: return None
    nj = re.sub(r"[\W_]+", "", n); ntoks = n.split()
    if n == qn or (nj and nj == qjoin): return 100, W_TITLE_FULL
    if len(nj) <= SHORT_NAME: return (88, W_TITLE_SHORT) if ntoks and all(t in qtoks for t in ntoks) else None
    if not f: return (90, W_TITLE_PARTIAL) if all(t in qtoks for t in ntoks) else None
    if (full := f.ratio(qn, n)) >= 86: return full, W_TITLE_FULL
    s = f.WRatio(qn, n)
    if s < 86: return None
    return (max(s, 90) if all(t in qtoks for t in ntoks) or nj in qjoin else s), W_TITLE_PARTIAL

def search(q, k=10, domain=None, explain=False):
    import math
    con = connect()
    terms = [strip_accents(w.lower()) for w in WORD.findall(q) if len(w) >= 2]
    keyterms = [t for t in terms if t not in STOP] or terms
    dfilter, dargs = (" AND d.domain=?", [domain]) if domain else ("", [])
    ranks, pweight, exact_add, exact = {}, {}, {}, {}
    sizes = dict(con.execute("SELECT path, count(*) FROM chunks GROUP BY path"))
    qkeys = keys_in(q, query=True)
    if qkeys:
        rows = con.execute(f"SELECT k.key, k.path, k.tier FROM keys k JOIN docs d ON d.path=k.path WHERE k.key IN ({','.join('?' * len(qkeys))}){dfilter}", list(qkeys) + dargs).fetchall()
        nd = {}
        for key, _, _ in rows: nd[key] = nd.get(key, 0) + 1
        rest = q
        for rx in (URL_RE, BARE_URL_RE, EMAIL_RE, LONGID_RE): rest = rx.sub(" ", rest)
        pure = not re.sub(r"[\W_]+", "", rest)   # only identifiers in the query: jump straight to their pages
        for key, path, tier in rows:
            exact[path] = min(tier, exact.get(path, 9))
            exact_add[path] = max(EXACT_BONUS[tier] if pure else W_EXACT_MIXED / (RRF_K + 1) / nd[key] / (1 + tier), exact_add.get(path, 0))
    if keyterms:   # strict AND, then AND with typo/compound alternatives, then OR
        best = {}
        for tier, fuzzy, op in ((-200, False, " AND "), (-100, True, " AND "), (0, True, " OR ")):
            try:
                rows = con.execute(f"SELECT c.path, bm25(fts, 8.0, 6.0, 2.0, 1.0) s FROM fts JOIN chunks c ON c.id=fts.rowid JOIN docs d ON d.path=c.path "
                                   f"WHERE fts MATCH ?{dfilter} ORDER BY s LIMIT 600", [op.join(fts_groups(con, keyterms, fuzzy))] + dargs).fetchall()
            except sqlite3.OperationalError: rows = []
            for path, s in rows:
                if path not in best: best[path] = tier + s / (1 + SIZE_DAMP * math.log(max(1, sizes.get(path, 1))))
        ranks["keyword"] = {p: i for i, p in enumerate(sorted(best, key=best.get))}
    qn = norm_name(q); qtoks = set(qn.split()); qjoin = re.sub(r"[\W_]+", "", qn); tscore, tw = {}, {}
    for path, title, aliases, idents in con.execute(f"SELECT path, title, aliases, idents FROM docs d WHERE 1=1{dfilter}", dargs):
        hits = [m for n in [title] + json.loads(aliases or "[]") if (m := title_match(qn, qtoks, qjoin, n))]
        if any(qn and qn == strip_accents(x.lower()) for x in json.loads(idents or "[]")): hits.append((100, W_TITLE_FULL))
        if hits: s, w = max(hits); tscore[path] = s + len(norm_name(title)) / 1000; tw[path] = w
    if tscore: ranks["title"] = {p: i for i, p in enumerate(sorted(tscore, key=lambda p: -tscore[p]))}; pweight["title"] = tw
    rows = con.execute(f"SELECT c.path, c.emb FROM chunks c JOIN docs d ON d.path=c.path WHERE c.emb IS NOT NULL{dfilter}", dargs).fetchall()
    if rows and (enc := get_encoder()):
        import numpy as np
        syn = [w for t in keyterms for w in SYN.get(t, [])]
        qv = enc.encode([f"query: {q}" + (f" ({' '.join(syn)})" if syn else "")])[0].astype(np.float32)
        sims = np.frombuffer(b"".join(r[1] for r in rows), dtype=np.float16).reshape(len(rows), -1).astype(np.float32) @ qv
        best = {}
        for (path, _), s in zip(rows, sims): best[path] = max(float(s), best.get(path, -1))
        ranks["semantic"] = {p: i for i, p in enumerate(sorted(best, key=lambda p: -best[p])[:300])}
    weights = {"keyword": W_KEYWORD, "title": W_TITLE_FULL, "semantic": W_SEMANTIC}; fused = dict(exact_add)
    for sig, rk in ranks.items():
        for p, r in rk.items(): fused[p] = fused.get(p, 0) + pweight.get(sig, {}).get(p, weights[sig]) / (RRF_K + r + 1)
    out = []
    for p in sorted(fused, key=lambda p: -fused[p])[:k]:
        title, dom, typ, upd = con.execute("SELECT title, domain, type, updated FROM docs WHERE path=?", (p,)).fetchone()
        r = dict(path=p, title=title, domain=dom, type=typ, updated=upd, score=round(fused[p], 5), snippet=snippet(con, p, keyterms))
        if explain:
            r["signals"] = {s: rk[p] + 1 for s, rk in ranks.items() if p in rk}
            if p in exact: r["signals"]["exact"] = "frontmatter" if exact[p] == 0 else "body"
        out.append(r)
    return out

def snippet(con, path, terms):
    rows = con.execute("SELECT heading, text FROM chunks WHERE path=?", (path,)).fetchall()
    h, t = max(rows, key=lambda r: sum(strip_accents(r[1].lower()).count(x) for x in terms)) if terms else rows[0]
    t = re.sub(r"\s+", " ", re.sub(r"\(Source:[^)]*\)", "", t)).strip()
    if terms:
        tl = strip_accents(t.lower()); pos = min([tl.find(x) for x in terms if x in tl] or [0]); t = t[max(0, pos - 80):pos + 220]
    return (f"[{h}] " if h else "") + t[:300]

